import{z as s,x as o,o as A,c as p,q as t,j as l,D as e,d as a,s as n,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"利率信用案例与收束","description":"","frontmatter":{"title":"利率信用案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-case-map.md","filePath":"quant/rc-case-map.md","lastUpdated":1791413859000}'),d={name:"quant/rc-case-map.md"};function C(c,E,D,u,h,f){const r=o("Mermaid");return A(),p("div",null,[E[2]||(E[2]=t('<h1 id="利率信用案例与收束" tabindex="-1">利率信用案例与收束 <a class="header-anchor" href="#利率信用案例与收束" aria-label="Permalink to &quot;利率信用案例与收束&quot;">​</a></h1><div class="epigraph"><p>危机是这门课的期末考试：先出题的总是资金与抵押品，及格的标准落在判据上——每个案例都在检验你把价格拆到了哪一层。</p><footer>—— 据 BIS Quarterly Review（2020 年 3 月期、2022 年 12 月期）相关评述整理</footer></div><p><a href="/quant/rc-regcap-pricing">上一课</a>把监管资本写回了报价，信用与资金单元到此闭环。本课程到此收束：本课用三个案例把利率线（曲线—Swaption—波动）与信用资金线（组合—指数—抵押—XVA—资本）串起来，每个案例停在本课程立过的判据上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>案例教学的风险是把故事当知识：听完 2008 与 2022，记住的是情节而不是可复用的检验。本课的问题不是「发生了什么」，而是课程立过的判据能否事前写进引擎与限额。三个案例各考一课：2020 年 3 月考联合分布，2022 年 9 月考抵押品螺旋，LIBOR 退场考曲线的合同地位。判定标准只有一个：判据能否在事前操作化，而不是事后解释。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>案例一：2020 年 3 月。疫情冲击下利率陡降、信用利差陡升，利率与信用的相关符号翻转。CVA 账簿发现：对手 PD 与暴露同向放大，按独立假设算的 CVA 系统性偏低。检验判据是<a href="/quant/rates-credit-hybrid">利率-信用混合定价</a>立的：错向进联合分布，不进系数；以及 <a href="/quant/cva-exposure-profile">CVA 暴露剖面 EPE</a>立的：EE 与 PD 的相关是模拟设定，不是可以事后乘上的折扣。过不了这两条的引擎，2020 年的减值不是黑天鹅，是设定缺陷的兑现。</p><p><span class="marginnote">错向（wrong-way）翻译一下：暴露与对手违约概率同向恶化——市场一动，你手里这份合同更值钱了，可对手偏偏更可能倒，两件坏事叠加，信用损失远比「两者独立」时大。正确做法是把它写进联合分布，而不是事后乘一个折扣系数。</span></p><p>案例二：2022 年 9 月英国。负债驱动投资（LDI）基金用长端 gilt 加回购杠杆匹配养老金负债，收益率上行触发追加保证金，被迫抛售 gilt，收益率再上行——<a href="/quant/rc-collateral-funding">抵押品与资金链</a>一课的折价—杠杆螺旋在国债市场重演，英格兰银行入场买债。判据有两条：风险上，杠杆的敏感对象是折价与保证金，不只是波动率，<a href="/quant/key-tenor-dv01">关键期限 DV01</a>的长端桶只回答一半问题；治理上，压力场景必须包含「抵押条款被触发」这条路径——只压收益率曲线、不压折价与追保的压力测试，测不到这次危机。</p><p><span class="marginnote">LDI 螺旋可以想成带杠杆的抢椅子游戏：收益率一升，追加保证金立刻要现金，基金只能在最薄的市场里卖最长的债券，卖压把收益率推得更高，下一轮追保更狠——自我强化的圆圈，直到央行坐进来当最后的买家。</span></p><p>案例三：LIBOR 退场（2014–2023）。无风险利率替代重建了整条曲线体系：贴现与投影分离的多曲线框架（<a href="/quant/multi-curve-ois">OIS 与多曲线</a>）从权宜变成标准，fallback 利差调整让存续合约平稳迁移，CMS 的凸性调整随构建更换重算（<a href="/quant/cms-convexity">CMS 凸性调整</a>）。判据是<a href="/quant/curve-bootstrap">自举曲线</a>立的：曲线构建是合同的一部分——插值坐标、日历与构建集变了，历史时间序列的连续性要人工论证，不能默认。</p><p><span class="marginnote">为什么曲线构建算「合同的一部分」：LIBOR 停报时数万亿美元合约没有自动换锚条款，fallback 利差要逐批谈判。构建集一换，同一天的同名利率会给出不同数值，支付数字随之改变；不加论证就把新旧序列接起来，回测与限额都会悄悄断链。</span></p>',12)),(A(),l(i,null,{default:e(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E6%A1%88%E4%BE%8B%E4%B8%80%EF%BC%9A2020%20%E9%94%99%E5%90%91%22%5D%20--%3E%20J1%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E8%81%94%E5%90%88%E5%88%86%E5%B8%83%EF%BC%8C%E4%B8%8D%E6%98%AF%E7%B3%BB%E6%95%B0%22%5D%0A%20%20C2%5B%22%E6%A1%88%E4%BE%8B%E4%BA%8C%EF%BC%9A2022%20LDI%20%E8%9E%BA%E6%97%8B%22%5D%20--%3E%20J2%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E6%8A%98%E4%BB%B7%E4%B8%8E%E4%BF%9D%E8%AF%81%E9%87%91%E6%98%AF%E7%8B%AC%E7%AB%8B%E7%8A%B6%E6%80%81%E5%8F%98%E9%87%8F%22%5D%0A%20%20C3%5B%22%E6%A1%88%E4%BE%8B%E4%B8%89%EF%BC%9ALIBOR%20%E9%80%80%E5%9C%BA%22%5D%20--%3E%20J3%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E6%9B%B2%E7%BA%BF%E6%9E%84%E5%BB%BA%E5%B1%9E%E4%BA%8E%E5%90%88%E5%90%8C%22%5D%0A%20%20J1%20--%3E%20END%5B%22%E6%94%B6%E6%9D%9F%EF%BC%9A%E6%AF%8F%E5%B1%82%E4%BB%B7%E6%A0%BC%E8%83%8C%E5%90%8E%E9%83%BD%E6%9C%89%E8%B5%84%E9%87%91%E4%B8%8E%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20J2%20--%3E%20END%0A%20%20J3%20--%3E%20END%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("三个案例合起来给出本课程的方法论。其一，价格是分层的：线性形状观点、期权化的分布观点、资金与抵押的成本、资本约束的租金，各层有自己的机制；混层归因会把资金成本记成 alpha（"),B("a",{href:"/quant/rc-xva-linkage"},"XVA 的联动"),a("）。其二，危机传导走资金链：折价、保证金、基差是最先动的变量，价格是结果不是原因（见"),B("a",{href:"/quant/rc-cds-index-basis"},"CDS 指数与基差"),a("与抵押课）。其三，判据先于模型：混合定价、暴露剖面、折价敏感度、曲线合同观，每条判据都能在事前写进引擎与限额，事后兑现只是它们的对账。利率线与信用线在最高处汇合：利率波动率的形状由央行日程与均值回复定形，信用组合的尾部由相关与回收定形，而两者最终通过同一条资金链进入同一张报价单——这正是两栏同课的原因。")],-1)),(A(),l(i,null,{default:e(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E5%86%B2%E5%87%BB%EF%BC%9A%E6%94%B6%E7%9B%8A%E7%8E%87%E8%B7%B3%E5%8D%87%E6%88%96%E5%88%A9%E5%B7%AE%E8%B5%B0%E9%98%94%22%5D%20--%3E%20MTM%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BC%B0%E5%80%BC%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20MTM%20--%3E%20MARGIN%5B%22%E8%BF%BD%E5%8A%A0%E4%BF%9D%E8%AF%81%E9%87%91%E9%80%9A%E7%9F%A5%22%5D%0A%20%20MARGIN%20--%3E%20SELL%5B%22%E8%A2%AB%E8%BF%AB%E6%8A%9B%E5%94%AE%E8%B5%84%E4%BA%A7%22%5D%0A%20%20SELL%20--%3E%20FIRE%5B%22%E6%8A%98%E4%BB%B7%E5%8A%A0%E6%B7%B1%E3%80%81%E4%BB%B7%E6%A0%BC%E5%86%8D%E8%B7%8C%22%5D%0A%20%20FIRE%20--%3E%7C%22%E8%9E%BA%E6%97%8B%E5%BE%AA%E7%8E%AF%22%7C%20MTM%0A%20%20BASE%5B%22%E5%9F%BA%E5%B7%AE%E4%B8%8E%E8%B5%84%E9%87%91%E9%9D%A2%E6%9C%80%E5%85%88%E5%BC%82%E5%8A%A8%22%5D%20--%3E%20EARLY%5B%22%E9%A2%86%E5%85%88%E4%BA%8E%E4%BB%B7%E6%A0%BC%E7%9A%84%E5%8F%AF%E8%A7%82%E6%B5%8B%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CB%5B%22%E5%A4%AE%E8%A1%8C%E6%88%96%E6%B5%81%E5%8A%A8%E6%80%A7%E5%B7%A5%E5%85%B7%E5%85%A5%E5%9C%BA%22%5D%20--%3E%20STOP%5B%22%E4%BB%8E%E5%A4%96%E9%83%A8%E6%89%93%E6%96%AD%E8%9E%BA%E6%97%8B%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">BIS 对 2020 年 3 月的评述把这轮抛售命名为「dash for cash」：卖出一一切可卖资产以换取现金与保证金；对 2022 年 gilt 事件的评述同样落在杠杆与保证金的结构上。两次的救市工具不同（美元流动性额度与直接买债），病理与判据相同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写危机史：三个案例只取与课程判据相接的截面。归因要防事后偏差：2020 年 CVA 的损失里，错向设定与流动性处置成本要分开记；2022 年 LDI 的规模估计随口径变化很大，引用要带出处与日期。收束之后，波动率交易、结构化产品、金融 ML 与风险体系各有课程，不在此展开。本课程的收束线是一条方法论：把每个价格拆到机制层，再按资金与约束拼回报价单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2020：错向是联合分布问题，独立假设的 CVA 在相关翻转时系统性失效。</li><li>2022：折价与保证金是独立的状态变量，压力测试必须触发抵押条款路径。</li><li>LIBOR 退场：曲线构建是合同的一部分，转换要论证历史连续性。</li><li>方法论：分层定价、资金链优先、判据先于模型，两线在资金链上汇合。</li><li>出处：据 BIS Quarterly Review（2020 年 3 月期、2022 年 12 月期）相关评述整理；各条判据出自本课程相应课，见文中链接。</li></ul>',5))])}const _=s(d,[["render",C]]);export{F as __pageData,_ as default};
